INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65088252', 65088252, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'KONSULTAN JUNIOR IT REGULATION PENYUSUNAN ANALISIS REGULASI PENGEMBANGAN SISTEM INFORMASI LOGBOOK PROYEK PEMBANGUNAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Memastikan proyek mengikuti kerangka tata kelola TI pemerintah, dan mengawasi agar proses pengembangan mematuhi best practice tata kelola proyek TI pemerintah. 2. Memastikan terlaksananya prosedur yang terkait dengan keamanan dan Perlindungan Data; 3. Mengidentifikasi kebutuhan penyusunan peraturan perundang-undangan dan/atau peraturan kebijakan terkait penyelenggaraan sistem informasi pemerintahan di bidang perencanaan penganggaran, khususnya dalam kaitan dengan pengembangan Sistem Informasi Logbook Proyek; 4. Melakukan analisa regulasi dalam rangka penyelarasan dan sinkronisasi regulasi yang tengah disusun dengan regulasi perencanaan penganggaran eksisting; 5. Melakukan penyusunan peraturan perundang-undangan dan/atau peraturan kebijakan terkait penyelenggaraan sistem informasi pemerintahan di bidang perencanaan penganggaran, khususnya dalam kaitan dengan pengembangan Sistem Informasi Logbook', '1. Memiliki pendidikan minimal S1 di bidang Hukum (dibuktikan dengan ijazah jenjang pendidikan); 2. Memiliki pengalaman kerja minimal 2 (dua) tahun di instansi pemerintahan (dibuktikan dengan surat referensi/kontrak kerja); 3. Memiliki pengalaman kerja minimal 2 (dua) tahun berkaitan dengan proses penyusunan peraturan perundang-undangan dan peraturan kebijakan di lingkup perencanaan penganggaran (dibuktikan dengan surat referensi/kontrak kerja); 4. Memiliki kemampuan yang baik dan berpengalaman dalam menganalisis serta menyusun peraturan perundang-undangan dan peraturan kebijakan terkait penyelenggaraan sistem informasi pemerintahan dan proses perencanaan penganggaran pembangunan nasional, pengalaman berkoordinasi dengan stakeholders terkait.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1928340);
